[QueryRangeFunction]
public static str getDiscountOfferTypes()
{
    str queryRange = next getDiscountOfferTypes();

    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        queryRange = queryRangeConcat(queryRange, queryValue(RetailDiscountOfferTypeBase::FreeItem));
    }

    return queryRange;
}
